   if(job.action==='wash'){if(work?.stage?.startsWith('wash')||!data.dirty)return false;data.dirty=0;data.dirtyMugs=[];persist();return true;}
   if(job.action==='refill')return coffeeProvider?.bar?.staffRefill(job.slot)||false;
   const o=orders.find(o=>o.id===job.order),p=guests.find(p=>p.id===o?.person);if(!o||o.cancelled||o.paid||!p)return false;
   if(job.action==='pickup'){const m=marble.find(m=>m.order===o.id&&!m.carrier);if(!m||o.takeaway||p.cafeVisit.state!=='table-wait'||!p.seat)return false;m.carrier=id;return {cup:m.cup,next:{...job,action:'deliver',at:[p.seat.at[0],p.seat.at[1]+30],seconds:.6,label:'Bringing '+(o.foodName||'coffee')+' to '+p.name.split(' ')[0]}};}
   if(job.action==='deliver'){const i=marble.findIndex(m=>m.order===o.id&&m.carrier===id);if(i<0||p.cafeVisit.state!=='table-wait'||!p.seat)return false;const m=marble[i];marble.splice(i,1);if(!pay(p,o,true))return false;p.coffeeCup=m.cup;p.consumeTime=0;setState(p,'drink',65+random()*40+(gathering()?25:0));onEffect('cafeCup');return true;}
